void NativeBackend::present(const wchar_t*capture){p->begin();ComPtr<ID3D12Resource>read;D3D12_PLACED_SUBRESOURCE_FOOTPRINT fp={};UINT64 size=0;if(capture){auto d=p->back[p->index]->GetDesc();UINT rows;UINT64 row;p->dev->GetCopyableFootprints(&d,0,1,0,&fp,&rows,&row,&size);auto desc=bd(size);auto heap=hp(D3D12_HEAP_TYPE_READBACK);ck(p->dev->CreateCommittedResource(&heap,D3D12_HEAP_FLAG_NONE,&desc,D3D12_RESOURCE_STATE_COPY_DEST,nullptr,IID_PPV_ARGS(&read)),"Native screenshot readback");p->transition(p->back[p->index].Get(),D3D12_RESOURCE_STATE_RENDER_TARGET,D3D12_RESOURCE_STATE_COPY_SOURCE);D3D12_TEXTURE_COPY_LOCATION a={},b={};a.pResource=p->back[p->index].Get();a.Type=D3D12_TEXTURE_COPY_TYPE_SUBRESOURCE_INDEX;b.pResource=read.Get();b.Type=D3D12_TEXTURE_COPY_TYPE_PLACED_FOOTPRINT;b.PlacedFootprint=fp;p->list->CopyTextureRegion(&b,0,0,0,&a,nullptr);p->transition(p->back[p->index].Get(),D3D12_RESOURCE_STATE_COPY_SOURCE,D3D12_RESOURCE_STATE_PRESENT);}else p->transition(p->back[p->index].Get(),D3D12_RESOURCE_STATE_RENDER_TARGET,D3D12_RESOURCE_STATE_PRESENT);ck(p->list->Close(),"Native close frame");ID3D12CommandList*cmds[]={p->list.Get()};p->queue->ExecuteCommandLists(1,cmds);ck(p->swap->Present(1,0),"Native normal Present");ck(p->queue->Signal(p->fence.Get(),++p->serial),"Native frame fence");p->values[p->index]=p->serial;p->recording=false;p->frames++;if(read){p->wait(p->serial);BYTE*data;D3D12_RANGE range={0,(SIZE_T)size};ck(read->Map(0,&range,(void**)&data),"Native screenshot fence/map");savePNG(capture,p->w,p->h,data+fp.Offset,fp.Footprint.RowPitch);D3D12_RANGE empty={0,0};read->Unmap(0,&empty);}}
void NativeBackend::resize(unsigned w,unsigned h){if(!w||!h||w==p->w&&h==p->h)return;if(p->recording)present();p->idle();for(auto&t:p->back)t.Reset();p->depth.Reset();ck(p->swap->ResizeBuffers(Impl::Num,w,h,DXGI_FORMAT_UNKNOWN,0),"Native resize");p->w=w;p->h=h;p->size();for(auto&v:p->values)v=0;}
unsigned NativeBackend::width()const{return p->w;}unsigned NativeBackend::height()const{return p->h;}uint64_t NativeBackend::frame()const{return p->frames;}
